type Pilha[T any] struct{ itens []T }

func (p *Pilha[T]) Push(x T) { p.itens = append(p.itens, x) }

func (p *Pilha[T]) Pop() (T, bool) {
	var zero T
	if len(p.itens) == 0 {
		return zero, false
	}
	x := p.itens[len(p.itens)-1]
	p.itens = p.itens[:len(p.itens)-1]
	return x, true
}

package main

import (
	"bufio"
	"cmp"
	"errors"
	"fmt"
	"io"
	"maps"
	"os"
	"slices"
	"strings"
	"unicode"
)

type Entry struct {
	Word  string
	Count int
}

// count lê r palavra a palavra e devolve as frequências.
func count(r io.Reader) (map[string]int, error) {
	freq := make(map[string]int)
	sc := bufio.NewScanner(r)
	sc.Split(bufio.ScanWords)
	for sc.Scan() {
		w := strings.ToLower(strings.TrimFunc(sc.Text(),
			func(r rune) bool { return !unicode.IsLetter(r) }))
		if w != "" {
			freq[w]++
		}
	}
	return freq, sc.Err()
}

func top(freq map[string]int, n int) []Entry {
	es := make([]Entry, 0, len(freq))
	for w, c := range maps.All(freq) {
		es = append(es, Entry{w, c})
	}
	slices.SortFunc(es, func(a, b Entry) int {
		return cmp.Or(cmp.Compare(b.Count, a.Count),
			strings.Compare(a.Word, b.Word))
	})
	return es[:min(n, len(es))]
}

func run(r io.Reader, w io.Writer) error {
	freq, err := count(r)
	if err != nil {
		return fmt.Errorf("contando palavras: %w", err)
	}
	if len(freq) == 0 {
		return errors.New("entrada vazia")
	}
	for _, e := range top(freq, 5) {
		fmt.Fprintf(w, "%4d  %s\n", e.Count, e.Word)
	}
	return nil
}

func main() {
	if err := run(os.Stdin, os.Stdout); err != nil {
		fmt.Fprintln(os.Stderr, "erro:", err)
		os.Exit(1)
	}
}

func TestRun(t *testing.T) {
	var out bytes.Buffer
	err := run(strings.NewReader("a b a"), &out)
	if err != nil {
		t.Fatal(err)
	}
	want := "   2  a\n   1  b\n"
	if out.String() != want {
		t.Errorf("got %q, want %q", out.String(), want)
	}
}
